using System.Globalization;
using System.Reflection;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Build.Framework;
using Microsoft.Build.Utilities;

namespace CsCom.Build;

/// <summary>
/// Generates the interop code of the <c>CsComReference</c> items of a project with the bundled cscom tool, which runs on .NET 10
/// as a separate process, unless the code generated by a previous build is up to date.
/// </summary>
/// <remarks>
/// The task writes the items and the properties into a JSON request file, which the hidden <c>build-generate</c> command of the
/// tool reads. The tool records the hash of the request, the files it read and the files it generated in a state file; when the
/// hash is the same and none of these files changed, the tool is not run.
/// </remarks>
public sealed class CsComGenerate : ToolTask
{
    private const string RequestFileName = "cscom.request.json";
    private const string StateFileName = "cscom.state";

    private static readonly string Version = GetVersion();

    // The metadata of the CsComReference items passed to the generator.
    private static readonly string[] ReferenceMetadata =
    [
        "Namespace", "ReferencePath", "Config", "EventStyle", "StructProperties", "OverloadsForDefaultValues",
        "DateMarshalling", "CurrencyMarshalling", "BoolMarshalling", "BstrMarshalling", "SafeArrayMarshalling",
    ];

    private string _commandLine = string.Empty;

    /// <summary>Gets or sets the <c>CsComReference</c> items.</summary>
    [Required]
    public ITaskItem[] References { get; set; } = [];

    /// <summary>Gets or sets the <c>CsComLibrary</c> items: the namespaces and the configuration files of libraries by name.</summary>
    public ITaskItem[] Libraries { get; set; } = [];

    /// <summary>Gets or sets the directory of the project; relative paths are relative to it.</summary>
    [Required]
    public string ProjectDirectory { get; set; } = string.Empty;

    /// <summary>Gets or sets the directory of the generated files.</summary>
    [Required]
    public string OutputDirectory { get; set; } = string.Empty;

    /// <summary>Gets or sets the path of the assembly of the cscom tool.</summary>
    [Required]
    public string CsComPath { get; set; } = string.Empty;

    /// <summary>Gets or sets the path of the <c>dotnet</c> executable that runs the generator.</summary>
    public string DotNetHostPath { get; set; } = string.Empty;

    /// <summary>Gets or sets the target framework of the project.</summary>
    public string TargetFramework { get; set; } = string.Empty;

    /// <summary>Gets or sets the C# version of the project.</summary>
    public string LanguageVersion { get; set; } = string.Empty;

    /// <summary>Gets or sets where the support code comes from: <c>package</c>, <c>public</c> or <c>internal</c>.</summary>
    public string SupportCode { get; set; } = string.Empty;

    /// <summary>Gets or sets the namespace of the generated support code.</summary>
    public string SupportNamespace { get; set; } = string.Empty;

    /// <summary>Gets or sets whether runtime marshalling is disabled for the assembly.</summary>
    public string DisableRuntimeMarshalling { get; set; } = string.Empty;

    /// <summary>Gets or sets the default event style.</summary>
    public string EventStyle { get; set; } = string.Empty;

    /// <summary>Gets or sets the default structure properties.</summary>
    public string StructProperties { get; set; } = string.Empty;

    /// <summary>Gets or sets whether overloads are generated for default values by default.</summary>
    public string OverloadsForDefaultValues { get; set; } = string.Empty;

    /// <summary>Gets or sets the default representation of <c>DATE</c> values.</summary>
    public string DateMarshalling { get; set; } = string.Empty;

    /// <summary>Gets or sets the default representation of <c>CURRENCY</c> values.</summary>
    public string CurrencyMarshalling { get; set; } = string.Empty;

    /// <summary>Gets or sets the default representation of <c>VARIANT_BOOL</c> values.</summary>
    public string BoolMarshalling { get; set; } = string.Empty;

    /// <summary>Gets or sets the default representation of <c>BSTR</c> values.</summary>
    public string BstrMarshalling { get; set; } = string.Empty;

    /// <summary>Gets or sets the default representation of typed <c>SAFEARRAY</c>s.</summary>
    public string SafeArrayMarshalling { get; set; } = string.Empty;

    /// <summary>Gets the generated files.</summary>
    [Output]
    public ITaskItem[] GeneratedFiles { get; private set; } = [];

    /// <inheritdoc/>
    protected override string ToolName => "dotnet.exe";

    /// <inheritdoc/>
    protected override MessageImportance StandardOutputLoggingImportance => MessageImportance.Low;

    /// <inheritdoc/>
    protected override Encoding StandardOutputEncoding => Encoding.UTF8;

    /// <inheritdoc/>
    public override bool Execute()
    {
        string output = Path.GetFullPath(Path.Combine(ProjectDirectory, OutputDirectory));
        Directory.CreateDirectory(output);
        string request = CreateRequest(output);
        string hash = ComputeHash(request);
        string statePath = Path.Combine(output, StateFileName);
        var files = BuildState.ReadGeneratedFiles(statePath, hash);
        if (files is null)
        {
            string requestPath = Path.Combine(output, RequestFileName);
            File.WriteAllText(requestPath, request, new UTF8Encoding(encoderShouldEmitUTF8Identifier: false));
            _commandLine = $"exec \"{CsComPath}\" build-generate \"{requestPath}\" {hash}";
            if (!base.Execute())
            {
                return false;
            }

            files = BuildState.ReadGeneratedFiles(statePath, hash);
            if (files is null)
            {
                Log.LogError("CsCom: the cscom tool did not record the generated files in '{0}'.", statePath);
                return false;
            }
        }
        else
        {
            Log.LogMessage(MessageImportance.Normal, "CsCom: the interop code in '{0}' is up to date.", output);
        }

        GeneratedFiles = [.. files.Select(static f => new TaskItem(f))];
        return !Log.HasLoggedErrors;
    }

    /// <inheritdoc/>
    protected override string GenerateFullPathToTool()
    {
        if (!string.IsNullOrEmpty(DotNetHostPath) && File.Exists(DotNetHostPath))
        {
            return DotNetHostPath;
        }

        string? path = Environment.GetEnvironmentVariable("PATH");
        return path?.Split(Path.PathSeparator)
            .Where(static directory => directory.Length > 0)
            .Select(directory => Path.Combine(directory.Trim('"'), ToolName))
            .FirstOrDefault(File.Exists) ?? ToolName;
    }

    /// <inheritdoc/>
    protected override string GenerateCommandLineCommands() => _commandLine;

    /// <inheritdoc/>
    protected override string GetWorkingDirectory() => ProjectDirectory;

    /// <inheritdoc/>
    protected override bool HandleTaskExecutionErrors() => !Log.HasLoggedErrors && base.HandleTaskExecutionErrors();

    private static string ComputeHash(string request)
    {
        using var sha256 = SHA256.Create();
        byte[] hash = sha256.ComputeHash(Encoding.UTF8.GetBytes(request));
        return string.Concat(hash.Select(static b => b.ToString("x2", CultureInfo.InvariantCulture)));
    }

    private static string GetVersion()
    {
        string? version = typeof(CsComGenerate).Assembly.GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion;
        return version is null ? string.Empty : version.Split('+')[0];
    }

    // The request of the generator, see CsCom.LibrarySets.BuildRequest.
    private string CreateRequest(string output)
    {
        var json = new JsonWriter();
        json.Property("toolVersion", Version);
        json.Property("projectDirectory", Path.GetFullPath(ProjectDirectory));
        json.Property("outputDirectory", output);
        json.Property("targetFramework", TargetFramework);
        json.Property("languageVersion", LanguageVersion);
        json.Property("supportCode", SupportCode);
        json.Property("supportNamespace", SupportNamespace);
        json.Property("disableRuntimeMarshalling", DisableRuntimeMarshalling);
        json.Property("eventStyle", EventStyle);
        json.Property("structProperties", StructProperties);
        json.Property("overloadsForDefaultValues", OverloadsForDefaultValues);
        json.Property("dateMarshalling", DateMarshalling);
        json.Property("currencyMarshalling", CurrencyMarshalling);
        json.Property("boolMarshalling", BoolMarshalling);
        json.Property("bstrMarshalling", BstrMarshalling);
        json.Property("safeArrayMarshalling", SafeArrayMarshalling);
        json.StartArray("references");
        foreach (var reference in References)
        {
            json.StartObject();
            json.Property("source", reference.ItemSpec);
            foreach (string name in ReferenceMetadata)
            {
                json.Property(char.ToLowerInvariant(name[0]) + name.Substring(1), reference.GetMetadata(name));
            }

            json.EndObject();
        }

        json.EndArray();
        json.StartArray("libraries");
        foreach (var library in Libraries)
        {
            json.StartObject();
            json.Property("name", library.ItemSpec);
            json.Property("namespace", library.GetMetadata("Namespace"));
            json.Property("config", library.GetMetadata("Config"));
            json.EndObject();
        }

        json.EndArray();
        return json.ToString();
    }
}
